const entries=families.map(([id,name,status,purpose,review])=>({id,name,status,purpose,review}));
function catalogue(query='',sort='name',counts={}){const q=query.trim().toLowerCase();return entries.filter(e=>Object.values(e).join(' ').toLowerCase().includes(q)).sort((a,b)=>sort==='trends'?(counts[b.id]||0)-(counts[a.id]||0)||a.name.localeCompare(b.name):a.name.localeCompare(b.name));}
function paginate(rows,page=1,size=6){if(!Number.isInteger(size)||size<1)throw Error('Invalid page size');const pages=Math.max(1,Math.ceil(rows.length/size));const current=Math.min(pages,Math.max(1,Number.isInteger(page)?page:1));return {rows:rows.slice((current-1)*size,current*size),page:current,pages,total:rows.length};}
function draft(entry,fields){return ['RASNIKI ACGI — UNREVIEWED DRAFT','Category: '+entry.name,'Category status: '+entry.status,'Title: '+(fields.title.trim()||'Untitled'),'Purpose / intended audience: '+(fields.purpose.trim()||'Not specified'),'Declared locations: '+(fields.locations.trim()||'Not specified'),'Owner / rights basis: '+(fields.rights.trim()||'Not established'),'Acceptance check: '+(fields.acceptance.trim()||'Not specified'),'','PROPOSED SCOPE',entry.purpose,'','REVIEW REQUIREMENTS',entry.review,'Confirm evidence, permissions, costs, dependencies, and failure behavior.','Record authoritative sources and appropriate review before relying on legal, medical, emergency, or safety claims.','','SPEC TO PRODUCT','1. Confirm the need and authorized scope.','2. Identify required inputs, outputs, and resources.','3. Build a bounded prototype.','4. Run the stated acceptance check.','5. Review effects, limitations, and unresolved questions.','6. Publish only the reviewed scope and maintain corrections.','','This generated outline is not the implementation or approval of the proposed product.'].join('\n');}
function bitflip(value,bit){if(!/^\d+$/.test(String(value))||!/^\d+$/.test(String(bit)))throw Error('Use whole decimal numbers');const v=Number(value),b=Number(bit);if(v<0||v>255||b<0||b>7)throw Error('Value must be 0–255 and bit 0–7');return v^(1<<b);}
function exact(a,b,op){if(!/^-?\d+$/.test(a)||!/^-?\d+$/.test(b)||a.length>1000||b.length>1000)throw Error('Use signed integers up to 1000 characters');if(!['add','multiply'].includes(op))throw Error('Unsupported operation');return String(op==='add'?BigInt(a)+BigInt(b):BigInt(a)*BigInt(b));}
